import java.io.*;import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.tags.*;class assetsInspectBoss{public static void main(String[]a)throws Exception{var s=new SWF(new FileInputStream(a[0]),false);for(var c:s.getCharacters(false).values())if(c instanceof DefineSpriteTag d)for(var f:d.getTimeline().getFrames())for(var l:f.layers.values())if(l.instanceName!=null&&(l.instanceName.toLowerCase().contains("coll")||l.instanceName.toLowerCase().contains("hit")||l.instanceName.contains("boss")||l.instanceName.contains("angry")))System.out.println(d.spriteId+" frame "+(f.frame+1)+" name "+l.instanceName+" child "+l.characterId+" time "+l.time);}}
